#include <stdio.h>

int hammingDistance(int x, int y) {
    unsigned int z = (unsigned int)(x ^ y);
    int distance = 0;
    while (z != 0U) {
        z &= z - 1U;
        ++distance;
    }
    return distance;
}

code.C++:
class Solution {
public:
    int hammingDistance(int x, int y) {
        unsigned int z = static_cast<unsigned int>(x ^ y);
        int distance = 0;
        while (z != 0) {
            z &= (z - 1);
            ++distance;
        }
        return distance;
    }
};

